"""(v2: the same plus debug outputs for the trained settings; modules are named hexn_lattice_<shape>_v2.) Generate the Verilog of a Hex-N 12-wire detector bank on the hex lattice with edge bridges (layout: tools/hexn_lattice_v1.py). Usage: hexn_lattice_gen_v8.py SHAPE > rtl/gen/hexn_lattice_SHAPE_v8.v
The module has the same ports and parameters as hexn_bank_v1 (K = cells of the shape, NB = 12). Class k = cell k (order of the shape). Each bridge is a 4-bit register; the first bridge of a line takes its group straight from s_bits."""
import sys, os, importlib.util
sp = importlib.util.spec_from_file_location("lat", os.path.join(os.path.dirname(os.path.abspath(__file__)), "hexn_lattice_v1.py")); lat = importlib.util.module_from_spec(sp); sp.loader.exec_module(lat)
name = sys.argv[1]; cells = lat.shape(name); idx, br = lat.layout(cells); K = len(cells); settle = max(v["pos"] for v in br.values()) + 1
bid = {k: i for i, k in enumerate(sorted(br, key=lambda k: (idx[k[0]], k[1])))}
o = []
o.append("`default_nettype none")
o.append(f"// Generated by tools/hexn_lattice_gen_v8.py {name}: {K} detectors on a hex lattice, {len(br)} edge bridges (3 per cell, 4 flip-flops each), settle {settle} clocks. DO NOT EDIT; regenerate.")
o.append(f"module hexn_lattice_{name}_v8 #(parameter K = {K}, parameter NB = 12, parameter AW = 6, parameter S = 16, parameter CB = 6, parameter ACCMODE = 0) (")
o.append("    input  wire clk, input wire rst, input wire tr_start, input wire [2:0] tr_cmd, output wire tr_busy,")
o.append("    input  wire [NB-1:0] s_bits, input wire [$clog2(K)-1:0] s_label, input wire [CB-1:0] t_in,")
o.append("    input  wire run_start, output wire run_busy, output wire run_done, output wire ans_valid, output wire [$clog2(K)-1:0] ans_class, output wire [4*K-1:0] cnt_flat,")
o.append("    output wire [K*NB-1:0] dbg_wpos, output wire [K*NB-1:0] dbg_wneg, output wire [K*AW-1:0] dbg_thr, output wire [K*16-1:0] dbg_sump, output wire [K*16-1:0] dbg_sumn, output wire [K*8-1:0] dbg_net, output wire [K*8-1:0] dbg_fwd, input wire [$clog2(K*NB+1)-1:0] cap_ad, output wire [7:0] cap_data, output wire [7:0] cap_n, input wire [$clog2(K*NB+1)-1:0] peek_ad, output wire signed [CB-1:0] peek_data);")
o.append(f"    reg [3:0] bridge [0:{len(br)-1}];")
o.append("    always @(posedge clk) begin")
for k, b in sorted(bid.items(), key=lambda x: x[1]):
    src = f"s_bits[{4*k[1]} +: 4]" if br[k]["up"] is None else f"bridge[{bid[br[k]['up']]}]"
    o.append(f"        bridge[{b}] <= {src};   // cell {idx[k[0]]} {k[0]} group {'ABC'[k[1]]} (line position {br[k]['pos']})")
o.append("    end")
o.append("    wire [K*NB-1:0] rx_flat;")
for c in cells:
    i = idx[c]; o.append(f"    assign rx_flat[{i}*NB +: NB] = {{bridge[{bid[(c,2)]}], bridge[{bid[(c,1)]}], bridge[{bid[(c,0)]}]}};   // cell {i} {c}")
o.append(f"    hexn_bank_v9 #(.K(K), .NB(NB), .AW(AW), .S(S), .CB(CB), .SETTLE({settle}), .ACCMODE(ACCMODE)) bank(.clk(clk), .rst(rst), .tr_start(tr_start), .tr_cmd(tr_cmd), .tr_busy(tr_busy), .s_bits(s_bits), .rx_flat(rx_flat), .s_label(s_label), .t_in(t_in),")
o.append("        .run_start(run_start), .run_busy(run_busy), .run_done(run_done), .ans_valid(ans_valid), .ans_class(ans_class), .cnt_flat(cnt_flat), .dbg_wpos(dbg_wpos), .dbg_wneg(dbg_wneg), .dbg_thr(dbg_thr), .dbg_sump(dbg_sump), .dbg_sumn(dbg_sumn), .dbg_net(dbg_net), .dbg_fwd(dbg_fwd), .cap_ad(cap_ad), .cap_data(cap_data), .cap_n(cap_n), .peek_ad(peek_ad), .peek_data(peek_data));")
o.append("endmodule"); o.append("`default_nettype wire")
print("\n".join(o))
